    CONSTRAINT uk_preferencessubcategory_subcategoryforacategory UNIQUE (catcode, name)
);

CREATE TABLE dbo.presaledetail (
    presaleinvcode integer NOT NULL,
    purinvcode integer NULL,
    icode integer NOT NULL,
    gcode smallint NOT NULL,
    batch citext NOT NULL,
    expiry timestamp(3) NOT NULL,
    packunits smallint NOT NULL,
    qty numeric(15,4) NOT NULL DEFAULT 1,
    bonusqty numeric(15,4) NOT NULL DEFAULT 0,
    saleprice numeric(12,2) NOT NULL DEFAULT 0,
    discperc numeric(5,2) NOT NULL DEFAULT 0,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    purrowid integer NULL,
    itemdescription citext NULL
);

CREATE TABLE dbo.presaleheader (
    presaleinvcode integer NOT NULL,
    date timestamp(3) NOT NULL DEFAULT localtimestamp(3),
    custcode smallint NOT NULL,
    usercode smallint NOT NULL,
    remarks citext NULL,
    posted citext NOT NULL DEFAULT 'N',
    postedby smallint NULL,
    postdate timestamp(3) NULL,
    saleinvcode integer NULL,
    custrefno citext NULL,
