    precautioncode smallint NOT NULL,
    CONSTRAINT pk_visitprecaution PRIMARY KEY (visitcode, precautioncode)
);

CREATE TABLE dbo.visitprescription (
    visitcode integer NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    icode integer NOT NULL,
    qty numeric(15,4) NOT NULL DEFAULT 1,
    diseasecode smallint NULL DEFAULT 1,
    dosagecode smallint NULL,
    dosagefactor smallint NULL,
    routecode smallint NULL,
    duration smallint NULL,
    date timestamp(3) NULL,
    inscode smallint NULL,
    details citext NULL,
    dosageunitcode smallint NOT NULL DEFAULT 1,
    dosagestrength citext NULL,
    totalqty numeric(15,4) NOT NULL DEFAULT 1,
    CONSTRAINT pk_visitprescription PRIMARY KEY (visitcode, rowid)
);

CREATE TABLE dbo.visitstatus (
    visitstatuscode smallint NOT NULL,
    name citext NOT NULL,
    CONSTRAINT pk_visitstatus_visitstatuscode PRIMARY KEY (visitstatuscode),
    CONSTRAINT uk_visitstatus_name UNIQUE (name)
);

CREATE TABLE dbo.visitsymptoms (
    visitcode integer NOT NULL,
    symptomcode integer NOT NULL,
    severitylevelcode smallint NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    duration integer NULL,
    details citext NULL,
    CONSTRAINT pk_visitsymptoms PRIMARY KEY (visitcode, rowid)
);

CREATE TABLE dbo.visittype (
    visittypecode smallint NOT NULL,
    name citext NOT NULL,
    CONSTRAINT pk_visittype_visittypecode PRIMARY KEY (visittypecode),
    CONSTRAINT uk_visittype_name UNIQUE (name)
);

CREATE TABLE dbo.visitvitals (
    visitcode integer NOT NULL,
    height1 smallint NULL,
    heightunit1 citext NOT NULL DEFAULT 'FT.',
    height2 smallint NULL,
    heightunit2 citext NOT NULL DEFAULT 'INCH',
    weight1 smallint NULL,
    weightunit1 citext NOT NULL DEFAULT 'KG',
    weight2 smallint NULL,
    weightunit2 citext NOT NULL DEFAULT 'G',
    temperaturevalue numeric(5,2) NULL,
    temperatureunit citext NOT NULL DEFAULT 'FH',
    pulserate smallint NULL,
    pulserhythm citext NOT NULL DEFAULT 'R',
    respiration smallint NULL,
    respirationrhythm citext NOT NULL DEFAULT 'R',
    bloodpressuresystolic smallint NULL,
    bloodpressurediastolic smallint NULL,
    vitalnotes citext NULL,
    bmi numeric(8,4) NULL,
    bsamethod smallint NULL,
    bsa numeric(8,4) NULL,
    spo2 citext NULL,
    CONSTRAINT pk_visitvitals_visitcode PRIMARY KEY (visitcode)
);

CREATE TABLE dbo.vochercategory (
    vochcatcode smallint NOT NULL,
    name citext NOT NULL,
    shortname citext NOT NULL,
    counter integer NOT NULL DEFAULT 0,
    posted citext NOT NULL DEFAULT 'N',
    systemtype smallint NOT NULL DEFAULT 0,
    journalvoucher smallint NOT NULL DEFAULT 0,
    headertreatment citext NULL,
    detailtreatment citext NULL,
    invoicebased smallint NOT NULL DEFAULT 0,
    invoicetype smallint NULL,
    autoposting citext NOT NULL DEFAULT 'N',
    voucherorder smallint NOT NULL DEFAULT 1,
    useforsms citext NOT NULL DEFAULT 'N',
    CONSTRAINT pk_vochercategory PRIMARY KEY (vochcatcode),
    CONSTRAINT vcnameuc UNIQUE (name),
    CONSTRAINT ix_vochercategory_shortname UNIQUE (shortname)
);

CREATE TABLE dbo.vochercategorydetail (
    vochcatcode smallint NOT NULL,
    subacccode smallint NOT NULL,
    CONSTRAINT pk_vochercategorydetail PRIMARY KEY (vochcatcode, subacccode)
);

CREATE TABLE dbo.vochercategoryheader (
    vochcatcode smallint NOT NULL,
    subacccode smallint NOT NULL,
    CONSTRAINT pk_vochercategoryheader PRIMARY KEY (vochcatcode, subacccode)
);

CREATE TABLE dbo.ward (
    wardcode smallint NOT NULL,
    name citext NOT NULL,
    description citext NULL,
    CONSTRAINT pk_ward PRIMARY KEY (wardcode),
    CONSTRAINT ix_ward UNIQUE (name)
);

CREATE TABLE dbo.weekdays (
    weekdaycode smallint NOT NULL,
    name citext NOT NULL,
    CONSTRAINT pk_weekdaycode_weekdays PRIMARY KEY (weekdaycode),
    CONSTRAINT uk_weekdaycode_weekdays UNIQUE (weekdaycode)
);

CREATE TABLE dbo.weekofmonth (
    weekofmonth smallint NOT NULL,
    name citext NOT NULL,
    CONSTRAINT pk_weekofmonth PRIMARY KEY (weekofmonth),
    CONSTRAINT uk_weekofmonth UNIQUE (name)
);

CREATE TABLE dbo.weighingscale (
    weighingscalecode smallint NOT NULL,
    name citext NOT NULL,
    manufacturer citext NULL,
    model citext NULL,
    scaleid citext NOT NULL DEFAULT '98',
    scaleidpos smallint NOT NULL DEFAULT 1,
    barcodelen smallint NOT NULL DEFAULT 13,
    itemstartpos smallint NOT NULL DEFAULT 3,
    itemendpos smallint NOT NULL DEFAULT 7,
    weightstartpos smallint NOT NULL DEFAULT 8,
    weightendpos smallint NOT NULL DEFAULT 12,
    CONSTRAINT pk_weighingscale PRIMARY KEY (weighingscalecode),
    CONSTRAINT uk_weighingscale_name UNIQUE (name)
);

CREATE TABLE dbo.windowtype (
    wintype smallint NOT NULL,
    name citext NOT NULL,
    CONSTRAINT pk_windowtype PRIMARY KEY (wintype),
    CONSTRAINT uq_windowtype_name UNIQUE (name)
);

CREATE TABLE dbo.workorder (
    workordercode integer NOT NULL,
    custcode smallint NOT NULL,
    date timestamp(3) NOT NULL DEFAULT localtimestamp(3),
    usercode smallint NOT NULL,
    initiatedby citext NULL,
    address citext NULL,
    contactno citext NULL,
    email citext NULL,
    availabilitytovisit citext NULL,
    complaint citext NULL,
    demand citext NULL,
    remarks citext NULL,
    approved citext NOT NULL DEFAULT 'N',
    approvedon timestamp(3) NULL,
    approvedby smallint NULL,
    posted citext NOT NULL DEFAULT 'N',
    postedon timestamp(3) NULL,
    postedby smallint NULL,
    workorderacccode integer NOT NULL DEFAULT 1,
    workordertypecode smallint NOT NULL DEFAULT 1,
    CONSTRAINT pk_workorder PRIMARY KEY (workordercode)
);

CREATE TABLE dbo.workorderaccount (
    workorderacccode integer NOT NULL,
    name citext NOT NULL,
    description citext NULL,
    "limit" numeric(12,2) NOT NULL DEFAULT 0,
    drcr citext NOT NULL DEFAULT 'D',
    CONSTRAINT pk_workorderaccount PRIMARY KEY (workorderacccode),
    CONSTRAINT uk_workorderacccode_name UNIQUE (name)
);

CREATE TABLE dbo.workorderassessment (
    workordercode integer NOT NULL,
    date timestamp(3) NOT NULL DEFAULT localtimestamp(3),
    usercode smallint NOT NULL,
    assessedon timestamp(3) NULL,
    assessedby citext NULL,
    assessment citext NULL,
    actionproposed citext NULL,
    remarks citext NULL,
    CONSTRAINT pk_workorderassessment PRIMARY KEY (workordercode)
);

CREATE TABLE dbo.workorderresource (
    workordercode integer NOT NULL,
    resourcecode integer NOT NULL,
    qty integer NOT NULL DEFAULT 1,
    cost numeric(15,2) NOT NULL DEFAULT 0,
    esttimereq timestamp(3) NULL,
    timetaken timestamp(3) NULL,
    date timestamp(3) NOT NULL DEFAULT localtimestamp(3),
    usercode smallint NOT NULL,
    remarks citext NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
);

CREATE TABLE dbo.workordertype (
    workordertypecode smallint NOT NULL,
    name citext NOT NULL,
    description citext NULL,
    CONSTRAINT pk_workordertype PRIMARY KEY (workordertypecode),
    CONSTRAINT uk_workordertype_name UNIQUE (name)
);

CREATE TABLE dbo.wrongitemtable (
    icode integer NULL,
    date timestamp(3) NULL
);

CREATE TABLE dbo.xray (
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    date timestamp(3) NOT NULL DEFAULT localtimestamp(3),
    patientcode integer NOT NULL,
    admissioncode integer NULL,
    xray citext NULL,
    xraydate timestamp(3) NULL,
    findingswithinnormallimits citext NULL,
    findingswithinnormallimitsxray citext NULL,
    cardiomegaloy citext NULL,
    cardiomegaloyxray citext NULL,
    findingsuggestiveofxray citext NULL,
    pulmonaryedemaxray citext NULL,
    pulmonaryembolismxray citext NULL,
    heartfailurexray citext NULL,
    chestinfectionxray citext NULL,
    pleuraleffusionxray citext NULL,
    pulmonarycocksxray citext NULL,
    massconsolidationxray citext NULL,
    bronchiactasisxray citext NULL,
    phenuthoraxxray citext NULL,
    haemothoraxxray citext NULL,
    copdxray citext NULL,
    otherxray citext NULL,
    usercode smallint NOT NULL DEFAULT 1,
    attendingdoctcode smallint NOT NULL DEFAULT 1,
    xrayadvised citext NOT NULL DEFAULT 'N',
    advisedetail citext NULL
);

CREATE TABLE dbo.zone (
    zonecode smallint NOT NULL,
    manfcode smallint NOT NULL,
    name citext NOT NULL,
    manager citext NULL,
    remarks citext NULL,
    icatcode smallint NULL,
    useforsms citext NOT NULL DEFAULT 'N',
    CONSTRAINT pk_zone_1__10 PRIMARY KEY (zonecode),
    CONSTRAINT znameuc UNIQUE (name)
);

CREATE TABLE dbo.zoneareas (
    zonecode smallint NOT NULL,
    areacode smallint NOT NULL,
    rowid integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    CONSTRAINT pk_zoneareas_1__10 PRIMARY KEY (zonecode, areacode)
);

CREATE TABLE dbo.zonecontactgroup (
    zonecode smallint NOT NULL,
    contactgroupcode smallint NOT NULL,
    CONSTRAINT pk_zonecontactgroup PRIMARY KEY (zonecode, contactgroupcode)
);
